per_hop.query:
SELECT ?dog1 ?dog1Breed ?dog2 ?dog2Breed WHERE {
  VALUES (?dog1 ?dog2) { 
    ("Banana Joe V Tani Kazari"@en "Villanuco de Las Encartaciones"@en)
  }
  OPTIONAL {
    ?dog1 wdt:P31 wd:Q144 . # instance of dog
    ?dog1 wdt:P105 ?dog1Breed . # taxon rank (breed)
  }
  OPTIONAL {
    ?dog2 wdt:P31 wd:Q144 .
    ?dog2 wdt:P105 ?dog2Breed .
  }
}

LIMIT 2

