  }
  OPTIONAL {
    ?dog2 wdt:P31 wd:Q144 .
    ?dog2 wdt:P105 ?dog2Breed .
  }
}

LIMIT 2

SELECT ?show ?host ?numShows WHERE {
  ?appearance rdf:type dbo:TelevisionAppearance ;
               dbo:actor dbr:Paul_Melba ;
               dbo:series ?show .
  ?show dbo:country dbr:United_Kingdom ;
        dbo:presenter ?host .
  ?host dbo:numberOfShows ?numShows .
  FILTER(?numShows = 23)
} LIMIT 10
